27	/// Core-facing handle to the optional SQLite-backed state runtime.
28	pub type StateDbHandle = Arc<codex_state::StateRuntime>;
29	
30	/// Initialize the state runtime when the `sqlite` feature flag is enabled. To only be used
31	/// inside `core`. The initialization should not be done anywhere else.
32	pub(crate) async fn init_if_enabled(
33	    config: &Config,
34	    otel: Option<&OtelManager>,
35	) -> Option<StateDbHandle> {
36	    if !config.features.enabled(Feature::Sqlite) {
37	        return None;
38	    }
39	    let runtime = match codex_state::StateRuntime::init(
40	        config.sqlite_home.clone(),
41	        config.model_provider_id.clone(),
42	        otel.cloned(),
43	    )
44	    .await
45	    {
46	        Ok(runtime) => runtime,
47	        Err(err) => {
48	            warn!(
49	                "failed to initialize state runtime at {}: {err}",
50	                config.sqlite_home.display()
51	            );
52	            if let Some(otel) = otel {
53	                otel.counter("codex.db.init", 1, &[("status", "init_error")]);
54	            }
55	            return None;
56	        }
57	    };
58	    let backfill_state = match runtime.get_backfill_state().await {
59	        Ok(state) => state,
60	        Err(err) => {
61	            warn!(
62	                "failed to read backfill state at {}: {err}",
63	                config.codex_home.display()
64	            );
65	            return None;
66	        }
67	    };
68	    if backfill_state.status != codex_state::BackfillStatus::Complete {
69	        let runtime_for_backfill = runtime.clone();
70	        let config = config.clone();
71	        let otel = otel.cloned();
72	        tokio::spawn(async move {
73	            metadata::backfill_sessions(runtime_for_backfill.as_ref(), &config, otel.as_ref())
74	                .await;
75	        });
76	    }
77	    Some(runtime)
78	}
