80	/// Get the DB if the feature is enabled and the DB exists.
81	pub async fn get_state_db(config: &Config, otel: Option<&OtelManager>) -> Option<StateDbHandle> {
82	    let state_path = codex_state::state_db_path(config.sqlite_home.as_path());
83	    if !config.features.enabled(Feature::Sqlite)
84	        || !tokio::fs::try_exists(&state_path).await.unwrap_or(false)
85	    {
