142	    let value = serde_json::to_value(cursor).ok()?;
143	    let cursor_str = value.as_str()?;
144	    let (ts_str, id_str) = cursor_str.split_once('|')?;
145	    if id_str.contains('|') {
146	        return None;
147	    }
